   385	function getPersonalDetailsForAccountIDs(accountIDs: number[] | undefined, personalDetails: OnyxInputOrEntry<PersonalDetailsList>): SetNonNullable<PersonalDetailsList> {
   386	    const personalDetailsForAccountIDs: SetNonNullable<PersonalDetailsList> = {};
   387	    if (!personalDetails) {
